package service

import("errors";"testing"
    "github.com/google/uuid";"github.com/onoja217/users-management-app/internal/models";"github.com/onoja217/users-management-app/internal/repository";"gorm.io/driver/sqlite";"gorm.io/gorm")
func TestSubjectServiceLifecycle(t *testing.T){db,e:=gorm.Open(sqlite.Open("file:subject-service-test?mode=memory&cache=shared"),&gorm.Config{});if e!=nil{t.Fatal(e)};if e=db.AutoMigrate(&models.Subject{});e!=nil{t.Fatal(e)};svc:=NewSubjectService(repository.NewSubjectRepository(db),db);v,e:=svc.Create(uuid.MustParse("00000000-0000-0000-0000-000000000001"),models.Subject{SchoolID:uuid.MustParse("00000000-0000-0000-0000-000000000001"),Code:"math",Name:"Mathematics"});if e!=nil{t.Fatal(e)};if v.Code!="MATH"{t.Fatalf("expected MATH, got %q",v.Code)};if e=svc.Update(uuid.MustParse("00000000-0000-0000-0000-000000000001"),v);e!=nil{t.Fatal(e)};if e=svc.Delete(uuid.MustParse("00000000-0000-0000-0000-000000000001"),v.ID);e!=nil{t.Fatal(e)};if _,e=svc.Get(uuid.MustParse("00000000-0000-0000-0000-000000000001"),v.ID);!errors.Is(e,ErrSubjectNotFound){t.Fatalf("expected not found, got %v",e)}}
func TestSubjectServiceRejectsDuplicates(t *testing.T){db,e:=gorm.Open(sqlite.Open("file:subject-duplicate-test?mode=memory&cache=shared"),&gorm.Config{});if e!=nil{t.Fatal(e)};if e=db.AutoMigrate(&models.Subject{});e!=nil{t.Fatal(e)};svc:=NewSubjectService(repository.NewSubjectRepository(db),db);if _,e=svc.Create(uuid.MustParse("00000000-0000-0000-0000-000000000001"),models.Subject{Code:"ENG",Name:"English"});e!=nil{t.Fatal(e)};if _,e=svc.Create(uuid.MustParse("00000000-0000-0000-0000-000000000001"),models.Subject{Code:"eng",Name:"English Language"});!errors.Is(e,ErrSubjectDuplicate){t.Fatalf("expected duplicate code, got %v",e)};if _,e=svc.Create(uuid.MustParse("00000000-0000-0000-0000-000000000001"),models.Subject{Code:"SCI",Name:"English"});!errors.Is(e,ErrSubjectDuplicate){t.Fatalf("expected duplicate name, got %v",e)}}
